package handler

import (
	"encoding/json"
	"fmt"
	"os"
	"testing"

	"github.com/carbogninalberto/assozeta/BE_GO/internal/apischema"
	"github.com/carbogninalberto/assozeta/BE_GO/internal/pdfrender"
)

// The Content-Disposition Django sets for a `version` value (generated by
// TESTS/adapters/django/api_schema.py).
func TestSchemaDispositionMatchesDjango(t *testing.T) {
	raw, err := os.ReadFile("../apischema/testdata/version_samples.json")
	if err != nil {
		t.Fatal(err)
	}
	var samples []struct {
		Version         string `json:"version"`
		YAMLDisposition string `json:"yaml_disposition"`
		JSONDisposition string `json:"json_disposition"`
	}
	if err := json.Unmarshal(raw, &samples); err != nil {
		t.Fatal(err)
	}
	checked := 0
	for _, sample := range samples {
		for format, want := range map[string]string{"yaml": sample.YAMLDisposition, "json": sample.JSONDisposition} {
			disposition := fmt.Sprintf(`inline; filename="%s (%s).%s"`, apischema.Title(), sample.Version, format)
			if !pdfrender.HeaderSafe(disposition) {
				continue
			}
			var latin []byte
			for _, r := range want {
				latin = append(latin, byte(r))
			}
			if got := pdfrender.HeaderBytes(disposition); got != string(latin) {
				t.Errorf("%s version %q: got %q, want %q", format, sample.Version, got, latin)
			}
			checked++
		}
	}
	if checked < 60 {
		t.Fatalf("only %d dispositions checked", checked)
	}
}
